<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useSession } from '../../stores/session'
import { api } from '../../shared/api/client'
import type { Candidate, PrivateTask, Resume, ResumeDetail, User } from '../../shared/api/types'
import { errorText, notify, time, processingError } from '../../shared/display'
const route = useRoute(), session = useSession()
const owner = ref(session.isAdmin ? String(route.query.owner_user_id ?? '') : ''), users = ref<User[]>([])
const prefix = computed(() => owner.value && session.isAdmin ? '/admin' : '/me')
function path(suffix: string) { return prefix.value + suffix + (owner.value && session.isAdmin ? (suffix.includes('?')?'&':'?')+'owner_user_id=' + encodeURIComponent(owner.value) : '') }
const items = ref<Resume[]>([]), detail = ref<ResumeDetail | null>(null), loading = ref(false), busy = ref(false), error = ref(''), configured = ref(false)
const file = ref<File | null>(null), names = ref(''), preview = ref(''), consent = ref(false), task = ref<PrivateTask | null>(null), fileInput = ref<HTMLInputElement | null>(null)
const canRead = computed(() => !!session.capabilities['resumes.read']), canUpload = computed(() => !!session.capabilities['resumes.upload'])
const active = computed(() => !!task.value && ['queued','running'].includes(task.value.state))
const dirty = computed(() => !!detail.value && preview.value !== detail.value.redacted_text)
const form = reactive({ education: 'unknown', education_region: 'unknown', graduation_date: '', major_codes: [] as string[], student: '', experience_months: '' as string | number, internship_months: '' as string | number, days_per_week: '' as string | number, skills: '' })
const majors: Record<string,string> = {computer_science:'计算机科学',software_engineering:'软件工程',artificial_intelligence:'人工智能',mathematics:'数学',communications:'通信工程',information_technology:'信息技术',electronics:'电子工程'}
const statuses: Record<string,string> = {queued:'等待本地提取',review:'请核对脱敏内容',parsing:'正在生成草稿',draft:'草稿待确认',confirmed:'资料已确认',failed:'提取未完成'}
const taskStates: Record<string,string> = {queued:'排队中',running:'处理中',succeeded:'已完成',failed:'处理失败',cancelled:'已取消，权限或资料发生变化'}
let generation = 0, polling = false
function assign(value: ResumeDetail) { detail.value = value; preview.value = value.redacted_text; consent.value = false; const c = value.draft; Object.assign(form,{education:c.education || 'unknown',education_region:c.education_region || 'unknown',graduation_date:c.graduation_date || '',major_codes:c.major_codes ?? [],student:c.student === null || c.student === undefined ? '' : String(c.student),experience_months:c.experience_months ?? '',internship_months:c.internship_months ?? '',days_per_week:c.days_per_week ?? '',skills:(c.skills ?? []).join('、')}) }
async function load() { const g = generation; loading.value=true; error.value=''; try {const result = await api<{items:Resume[];model_configured:boolean}>(path('/resumes?limit=100')); if(g===generation){items.value=result.items;configured.value=result.model_configured}}catch(e){if(g===generation)error.value=errorText(e)}finally{if(g===generation)loading.value=false} }
async function select(item: Resume) { if(!canRead.value)return; const g = ++generation; detail.value=null;task.value=null;error.value=''; try{const value=await api<ResumeDetail>(path('/resumes/'+item.id));if(g!==generation||!canRead.value)return;assign(value);if(value.resume.task_id){const result=await api<{task:PrivateTask}>(path('/tasks/'+value.resume.task_id));if(g===generation)task.value=result.task}}catch(e){if(g===generation)error.value=errorText(e)} }
function pick(event: Event) {const value=(event.target as HTMLInputElement).files?.[0] ?? null;if(value && value.size>10*1024*1024){error.value='简历不能超过 10 MiB。';file.value=null;return}file.value=value}
async function upload() {if(!file.value)return;busy.value=true;error.value='';try{const body=new FormData();body.append('file',file.value);names.value.split(/[、,，\n]/).map(s=>s.trim()).filter(Boolean).forEach(s=>body.append('sensitive_name',s));const result=await api<{resume:Resume}>(path('/resumes'),{method:'POST',body});file.value=null;if(fileInput.value)fileInput.value.value='';await load();await select(result.resume);notify('文件已私密保存，正在本地提取。')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function savePreview() {if(!detail.value)return;busy.value=true;try{await api(path('/resumes/'+detail.value.resume.id+'/preview'),{method:'PATCH',body:{revision:detail.value.resume.revision,text:preview.value}});await select(detail.value.resume);notify('已保存脱敏预览，请重新核对后授权。')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function parse() {if(!detail.value)return;busy.value=true;try{const result=await api<{task:PrivateTask}>(path('/resumes/'+detail.value.resume.id+'/parse'),{method:'POST',body:{revision:detail.value.resume.revision,consent:consent.value}});task.value=result.task;await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function number(value: string | number) {return value==='' ? null : Number(value)}
async function confirm() {if(!detail.value)return;busy.value=true;try{const candidate:Candidate={education:form.education,education_region:form.education_region,graduation_date:form.graduation_date,major_codes:form.major_codes,student:form.student===''?null:form.student==='true',experience_months:number(form.experience_months),internship_months:number(form.internship_months),days_per_week:number(form.days_per_week),skills:form.skills.split(/[、,，\n]/).map(s=>s.trim()).filter(Boolean),evidence:[]};await api(path('/resumes/'+detail.value.resume.id+'/confirm'),{method:'POST',body:{revision:detail.value.resume.revision,candidate,cloud_approved:consent.value}});await load();await select(detail.value.resume);notify('已保存新资料版本并设为当前版本。')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function activate(id: string) {if(!detail.value)return;busy.value=true;try{await api(path('/resumes/'+detail.value.resume.id+'/versions/'+id+'/activate'),{method:'POST'});await select(detail.value.resume);notify('已切换当前资料版本。')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function remove(item: Resume) {if(!window.confirm('删除这份简历及其资料版本、推荐结果？投递记录会保留，文件删除后无法恢复。'))return;busy.value=true;try{await api(path('/resumes/'+item.id),{method:'DELETE'});if(detail.value?.resume.id===item.id){generation++;detail.value=null;task.value=null}await load();notify('简历已删除。')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function poll() {if(polling||!active.value||!task.value)return;polling=true;const g=generation,id=task.value.id;try{const result=await api<{task:PrivateTask}>(path('/tasks/'+id));if(g!==generation)return;task.value=result.task;if(!['queued','running'].includes(result.task.state)){await load();if(detail.value&&canRead.value){const value=await api<ResumeDetail>(path('/resumes/'+detail.value.resume.id));if(g===generation)assign(value)}}}catch(e){if(g===generation)error.value=errorText(e)}finally{polling=false}}
const timer=window.setInterval(()=>void poll(),2000)
onBeforeUnmount(()=>{generation++;clearInterval(timer)})
watch([owner,canRead],()=>{generation++;detail.value=null;task.value=null;preview.value='';consent.value=false;void load()})
if(session.isAdmin)void api<{items:User[]}>('/admin/users?limit=100').then(r=>users.value=r.items).catch(e=>error.value=errorText(e))
void load()
</script>
<template>
 <section class="page-heading"><div><span class="eyebrow">先核对事实，再寻找机会</span><h1>我的简历与资料</h1><p>本地提取 → 检查脱敏预览 → 核对资料 → 保存当前版本。</p></div><RouterLink class="button secondary" :to="{path:'/recommendations',query:owner?{owner_user_id:owner}:{}}">查看岗位匹配</RouterLink></section>
 <label v-if="session.isAdmin" class="owner-picker">资料所属账号<select v-model="owner"><option value="">我的账号</option><option v-for="user in users.filter(u=>u.id!==session.user?.id)" :key="user.id" :value="user.id">{{ user.username }}</option></select></label>
 <p v-if="error" class="inline-error panel private-notice" role="alert">{{ error }}</p>
 <div v-if="!canUpload" class="panel private-notice"><strong>上传、阅读和匹配需要 VIP 权限。</strong><p>你仍可查看自己原有简历的文件信息，并删除简历及其衍生资料。</p></div>
 <section v-else class="panel private-notice"><form class="upload-form" @submit.prevent="upload"><label>上传 PDF / DOCX<input ref="fileInput" type="file" accept=".pdf,.docx" required @change="pick" /></label><label>需要隐去的姓名或别名<input v-model="names" maxlength="1200" placeholder="多个名字用顿号分隔，便于在全文中替换" /></label><button class="button primary" :disabled="busy || !file">{{ busy ? '处理中…' : '上传并本地提取' }}</button></form><p class="field-hint">最多 10 MiB。不支持扫描图片、加密或损坏文档。文件存储于私有目录，上传和本地提取不会调用模型。</p><p class="field-hint">{{ configured ? '已配置 DeepSeek，可在核对预览并授权后生成资料草稿。' : '模型尚未配置，可手动确认资料并使用资格规则；稍后配置密钥即可使用语义匹配。' }}</p></section>
 <div class="resume-layout">
  <section class="panel resume-list"><h2>简历文件</h2><p v-if="loading" class="muted">正在读取…</p><p v-else-if="!items.length" class="muted">还没有上传简历。</p><article v-for="item in items" :key="item.id" :class="{selected:detail?.resume.id===item.id}"><button class="resume-select" :disabled="!canRead || busy" @click="select(item)"><strong>{{ item.filename }}</strong><small>{{ (item.size_bytes/1024).toFixed(1) }} KiB · {{ time(item.created_at) }}</small><span>{{ statuses[item.status] ?? item.status }}</span></button><button class="text-button danger" :disabled="busy" @click="remove(item)">删除</button></article><p v-if="items.length===100" class="field-hint">展示最近 100 份文件。</p></section>
  <section v-if="detail && canRead" class="panel resume-editor"><header class="private-header"><h2>{{ detail.resume.filename }}</h2><a class="button secondary compact" :href="'/api/v1'+path('/resumes/'+detail.resume.id+'/download')">下载原文件</a></header>
   <p v-if="task" class="field-hint" role="status">任务：{{ taskStates[task.state] ?? task.state }}<span v-if="task.error_code">（{{ processingError(task.error_code) }}）</span></p>
   <p v-if="detail.resume.error_code" class="inline-error">{{ processingError(detail.resume.error_code) }}</p>
   <template v-if="detail.redacted_text"><h3>1. 核对脱敏预览</h3><p class="field-hint">系统会替换常见联系方式、姓名和地址，但无法保证完全匿名。请检查项目名称、公司和经历中的剩余身份线索；可以直接删除或改写下方内容。</p><label>将用于模型处理的文本<textarea v-model="preview" rows="9" maxlength="196608" :disabled="active || busy" /></label><button class="button secondary compact" :disabled="!dirty || active || busy" @click="savePreview">保存脱敏预览</button><p v-if="dirty" class="field-hint">请先保存预览，再解析或确认资料。</p>
   <label class="consent-row"><input v-model="consent" type="checkbox" :disabled="active || busy" />我已核对预览和下方资料，允许将脱敏后的内容发送给 DeepSeek，用于资料草稿和岗位语义比较。</label><button class="button secondary" :disabled="!configured || !consent || dirty || active || busy" @click="parse">使用模型生成待确认草稿</button>
   <h3>2. 确认求职资料</h3><p class="field-hint">模型草稿和手动输入都需要你核对。没有证据的条件保留“未知”，不会自动当作满足。</p>
   <details v-if="detail.draft.evidence?.length" class="history"><summary>查看草稿原文依据</summary><p v-for="(e,i) in detail.draft.evidence" :key="i"><strong>{{ e.field }}</strong>：{{ e.quote }}</p></details>
   <form @submit.prevent="confirm"><fieldset :disabled="active || busy || dirty" class="candidate-form"><div class="form-row"><label>最高学历<select v-model="form.education" aria-label="最高学历"><option value="unknown">未知</option><option value="associate">专科</option><option value="bachelor">本科</option><option value="master">硕士</option><option value="doctorate">博士</option></select></label><label>学历地区<select v-model="form.education_region" aria-label="学历地区"><option value="unknown">未知</option><option value="domestic">境内</option><option value="overseas">海外</option></select></label></div><div class="form-row"><label>毕业日期<input v-model="form.graduation_date" type="date" /></label><label>在校身份<select v-model="form.student" aria-label="在校身份"><option value="">未知</option><option value="true">在校生</option><option value="false">非在校生</option></select></label></div><div class="form-row"><label>工作经验（月）<input v-model="form.experience_months" type="number" min="0" max="1200" placeholder="未知留空" /></label><label>可实习时长（月）<input v-model="form.internship_months" type="number" min="0" max="60" placeholder="未知留空" /></label><label>每周可出勤天数<input v-model="form.days_per_week" type="number" min="0" max="7" placeholder="未知留空" /></label></div><div><span class="form-label">专业类别（未知可不选）</span><div class="major-options"><label v-for="(label,key) in majors" :key="key"><input v-model="form.major_codes" type="checkbox" :value="key" />{{ label }}</label></div></div><label>有依据的技能<input v-model="form.skills" maxlength="2000" placeholder="例如 Go、PostgreSQL；用顿号分隔" /></label><button class="button primary" type="submit">核对完成，保存为当前资料</button></fieldset></form>
   </template>
   <section v-if="detail.versions.length" class="profile-versions"><h3>已确认的版本</h3><article v-for="version in detail.versions" :key="version.id"><div><strong>{{ time(version.created_at) }}</strong><small>{{ version.candidate.skills?.join(' / ') || '未填写技能' }} · {{ version.cloud_approved ? '允许语义比较' : '仅本地规则' }}</small></div><span v-if="version.current" class="tag warm">当前版本</span><button v-else class="button secondary compact" :disabled="busy || active" @click="activate(version.id)">设为当前</button></article></section>
  </section>
  <section v-else class="panel empty-state"><h2>选择简历，核对你的求职资料</h2><p>已确认的版本会保留。切换版本后可重新匹配岗位。</p></section>
 </div>
</template>
